package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each claim's status log: one line per status it has had, oldest first. */
@Repository
public class ClaimLogRepository {

    private final JdbcTemplate jdbc;

    public ClaimLogRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Log the claim's status now, by the user on the date, at the due (null: n/a). */
    public void add(Claim claim, String by, LocalDate on, BigDecimal due) {
        jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, logged_on, due) VALUES (?, ?, ?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), claim.getStatus().name(), by, java.sql.Date.valueOf(on), due);
    }

    /** The date of the claim's first log line in the status, or null when it never had it. */
    public LocalDate firstOn(String sheetId, long claimId, ClaimStatus status) {
        List<LocalDate> on = jdbc.query("SELECT logged_on FROM claim_log WHERE sheet_id = ? AND claim_id = ? AND status = ?"
                + " ORDER BY id LIMIT 1", (rs, i) -> rs.getObject("logged_on", LocalDate.class),
                sheetId, claimId, status.name());
        return on.isEmpty() ? null : on.get(0);
    }

    /** The date of the claim's last log line in the status, or null when it never had it. */
    public LocalDate lastOn(String sheetId, long claimId, ClaimStatus status) {
        List<LocalDate> on = jdbc.query("SELECT logged_on FROM claim_log WHERE sheet_id = ? AND claim_id = ? AND status = ?"
                + " ORDER BY id DESC LIMIT 1", (rs, i) -> rs.getObject("logged_on", LocalDate.class),
                sheetId, claimId, status.name());
        return on.isEmpty() ? null : on.get(0);
    }

    /**
     * Each claim's status at the end of the day, by claim id, as its log records it: its last line (in log order)
     * logged on or before the day. A claim with no such line (added after it) is absent.
     */
    public Map<Long, ClaimStatus> statusesAsOf(String sheetId, LocalDate day) {
        Map<Long, ClaimStatus> statuses = new HashMap<>();
        jdbc.query("SELECT claim_id, status FROM claim_log WHERE sheet_id = ? AND logged_on <= ? ORDER BY id",
                rs -> {
                    statuses.put(rs.getLong("claim_id"), ClaimStatus.valueOf(rs.getString("status")));
                }, sheetId, java.sql.Date.valueOf(day));
        return statuses;
    }

    /** The sheet's log lines by claim id, each claim's oldest first, as {@code <STATUS> by <user> on <date> due=<due>}. */
    public Map<Long, List<String>> lines(String sheetId) {
        Map<Long, List<String>> lines = new HashMap<>();
        jdbc.query("SELECT claim_id, status, by_user, logged_on, due FROM claim_log WHERE sheet_id = ? ORDER BY id", rs -> {
            BigDecimal due = rs.getBigDecimal("due");
            lines.computeIfAbsent(rs.getLong("claim_id"), id -> new ArrayList<>())
                    .add(rs.getString("status") + " by " + rs.getString("by_user") + " on "
                            + rs.getObject("logged_on", LocalDate.class) + " due="
                            + (due == null ? "n/a" : due.setScale(2).toPlainString()));
        }, sheetId);
        return lines;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A claim as the screen shows it; `deferred` as of the sheet's today (deferred until a date after it, whatever its status), and `deferredUntil` the date it was last deferred until (null when never deferred), and `splitFrom` the number of the claim it was split off (null when none), and `lateEntry` whether it was added while its period was soft-closed, and `reminded` the last day a reminder was written (null when never), and `ref` its external reference (null when none), and `tags` its tags, sorted (empty when none), and `voidReason` the reason it was voided with (null when none), and `settleBatch` the number of the bulk settle batch that settled it (null when none), and `comments` its comments, oldest first, as `<user> on <date>: <text>`, and `lines` its lines, in the order added, as `<label> <qty> x <unit>`, and `added` where its adding stands in the order of changes (null: before every forward-only rate; see Rate#forClaim). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, String dueBy,
        java.util.List<String> log, boolean deferred, String deferredUntil, int proofs,
        String splitFrom, boolean lateEntry, String reminded, String ref,
        java.util.List<String> tags, String voidReason, java.util.List<String> comments,
        Integer settleBatch, java.util.List<String> lines, Long added) {

    /** The claim with its status log, oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, LocalDate today) {
        return from(claim, log, java.util.List.of(), java.util.List.of(), today);
    }

    /** The claim with its status log and its comments, each oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, java.util.List<String> comments,
            LocalDate today) {
        return from(claim, log, comments, java.util.List.of(), today);
    }

    /** The claim with its status log, its comments and its lines, each oldest first, as of the sheet's today. */
    public static ClaimResponse from(Claim claim, java.util.List<String> log, java.util.List<String> comments,
            java.util.List<String> lines, LocalDate today) {
        // Shown as deferred while its deferred-until date is after today, whatever became of the claim since.
        boolean deferred = claim.getDeferredUntil() != null && today != null && today.isBefore(claim.getDeferredUntil());
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(),
                claim.getNumber(), claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(), claim.getCorrects(),
                claim.getDueBy().toString(), log, deferred, claim.getDeferredUntil() == null ? null : claim.getDeferredUntil().toString(),
                claim.getProofs(), claim.getSplitFrom(), claim.isLateEntry(),
                claim.getRemindedOn() == null ? null : claim.getRemindedOn().toString(), claim.getRef(),
                claim.getTags() == null ? java.util.List.of() : java.util.List.of(claim.getTags().split(",")),
                claim.getVoidReason(), comments, claim.getSettleBatch(), lines, claim.getAddedSeq());
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.ViewAsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaims {
    public void respond(@Val SheetResponse sheet, @Val ViewAsOf asOf, SheetHistory history,
            ObjectResponse<List<ClaimResponse>> response) {
        response.send(history.view(sheet.id(), asOf.on(), jdbc -> {
            Map<Long, List<String>> lines = new ClaimLogRepository(jdbc).lines(sheet.id());
            Map<Long, List<String>> comments = new ClaimCommentRepository(jdbc).lines(sheet.id());
            Map<Long, List<String>> claimLines = new ClaimLineRepository(jdbc).lines(sheet.id());
            LocalDate today = new SheetRepository(jdbc).today(sheet.id());
            return new ClaimRepository(jdbc).list(sheet.id()).stream()
                    .map(c -> ClaimResponse.from(c, lines.getOrDefault(c.getId(), List.of()),
                            comments.getOrDefault(c.getId(), List.of()),
                            claimLines.getOrDefault(c.getId(), List.of()), today)).toList();
        }));
    }
}

